    --accent:#a8332a;
    --accent-soft:#c7503f;
    --rule:#2a2620;
    --gold:#b08a4a;
  }

  *{box-sizing:border-box;margin:0;padding:0}

  html,body{background:var(--bg);color:var(--ink);font-family:"IBM Plex Sans",sans-serif;font-weight:300;line-height:1.7;-webkit-font-smoothing:antialiased}

  body{
    background:
      radial-gradient(ellipse 80% 50% at 50% 0%, rgba(168,51,42,0.08), transparent 60%),
      radial-gradient(ellipse 60% 40% at 100% 100%, rgba(176,138,74,0.05), transparent 60%),
      var(--bg);
    min-height:100vh;
    overflow-x:hidden;
  }

  /* Grain overlay */
  body::before{
    content:"";
    position:fixed;inset:0;
    background-image:url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' width='200' height='200'><filter id='n'><feTurbulence type='fractalNoise' baseFrequency='0.9' numOctaves='2'/><feColorMatrix values='0 0 0 0 0.9 0 0 0 0 0.85 0 0 0 0 0.7 0 0 0 0.12 0'/></filter><rect width='100%' height='100%' filter='url(%23n)'/></svg>");
    opacity:0.5;
    pointer-events:none;
    mix-blend-mode:overlay;
    z-index:1;
  }

  .container{
    max-width:1100px;
    margin:0 auto;
    padding:0 32px;
    position:relative;
    z-index:2;
  }

  /* En-tête */
  header.masthead{
    padding:80px 0 40px;
    border-bottom:1px solid var(--rule);
  }
  .dateline{
    font-size:12px;
    letter-spacing:0.35em;
    text-transform:uppercase;
    color:var(--ink-mute);
    margin-bottom:32px;
    display:flex;
    align-items:center;
    gap:16px;
  }
  .dateline::after{
    content:"";
    flex:1;
    height:1px;
    background:var(--rule);
  }

  h1.title{
    font-family:"Cormorant Garamond",serif;
    font-weight:500;
    font-size:clamp(48px,8vw,104px);
    line-height:0.95;
    letter-spacing:-0.02em;
    color:var(--ink);
    margin-bottom:24px;
  }
  h1.title em{
    font-style:italic;
    font-weight:400;
    color:var(--accent-soft);
  }

  .lede{
    font-family:"Cormorant Garamond",serif;
    font-size:clamp(20px,2.4vw,28px);
    line-height:1.45;
    color:var(--ink-soft);
    max-width:760px;
    font-weight:400;
    font-style:italic;
  }

  .meta-bar{
    display:flex;
    flex-wrap:wrap;
    gap:48px;
    margin-top:48px;
    padding-top:32px;
    border-top:1px solid var(--rule);
  }
  .meta-bar div{
    font-size:13px;
    color:var(--ink-mute);
    letter-spacing:0.05em;
  }
  .meta-bar strong{
    display:block;
    color:var(--ink);
    font-weight:500;
    font-size:14px;
    margin-bottom:4px;
    letter-spacing:0.1em;
    text-transform:uppercase;
  }

  /* Section intro */
  .intro{
    padding:64px 0 32px;
    max-width:680px;
  }
  .intro p{
    margin-bottom:1.2em;
    color:var(--ink-soft);
    font-size:17px;
  }
  .intro p:first-letter{
    font-family:"Cormorant Garamond",serif;
    font-size:64px;
    line-height:0.85;
    float:left;
    padding:6px 12px 0 0;
    color:var(--accent-soft);
    font-weight:600;
  }

  /* Chronologie */
  section.timeline{
    padding:40px 0 80px;
    position:relative;
  }

  .section-label{
    font-size:12px;
    letter-spacing:0.4em;
    text-transform:uppercase;
    color:var(--ink-mute);
    margin-bottom:48px;
    display:flex;
    align-items:center;
    gap:16px;
  }
  .section-label::before{
    content:"§";
    color:var(--accent-soft);
    font-family:"Cormorant Garamond",serif;
    font-size:20px;
  }

  .timeline-rail{
    position:relative;
    padding-left:0;
  }

  .timeline-rail::before{
    content:"";
    position:absolute;
    left:140px;
    top:12px;
    bottom:12px;
    width:1px;
    background:linear-gradient(to bottom, transparent, var(--rule) 8%, var(--rule) 92%, transparent);
  }

  .event{
    display:grid;
    grid-template-columns:140px 1fr;
    gap:48px;
    padding:28px 0;
    position:relative;
    opacity:0;
    transform:translateY(20px);
    transition:opacity 0.9s cubic-bezier(.2,.7,.2,1), transform 0.9s cubic-bezier(.2,.7,.2,1);
  }
  .event.visible{
    opacity:1;
    transform:translateY(0);
  }
  .event::before{
    content:"";
    position:absolute;
    left:135px;
    top:38px;
    width:11px;
    height:11px;
    border-radius:50%;
    background:var(--bg);
    border:1px solid var(--ink-mute);
    transition:background 0.4s, border-color 0.4s, transform 0.4s;
  }
  .event.major::before{
    background:var(--accent);
    border-color:var(--accent);
    box-shadow:0 0 0 4px rgba(168,51,42,0.15);
  }
  .event:hover::before{
    transform:scale(1.3);
    border-color:var(--accent-soft);
  }
  .event.major:hover::before{
    background:var(--accent-soft);
  }

  .date{
    font-family:"Cormorant Garamond",serif;
    font-size:22px;
    font-weight:500;
    color:var(--ink);
    line-height:1.1;
    padding-top:32px;
    text-align:right;
  }
  .date .day{
    display:block;
    font-size:42px;
    font-weight:600;
    color:var(--accent-soft);
    letter-spacing:-0.02em;
  }
  .date .month{
    display:block;
    font-size:13px;
    letter-spacing:0.2em;
    text-transform:uppercase;
    color:var(--ink-mute);
    margin-top:2px;
    font-family:"IBM Plex Sans",sans-serif;
    font-weight:400;
  }

  .event-body{
    padding:32px 0 0 40px;
    border-top:1px solid transparent;
  }
  .event-body h3{
    font-family:"Cormorant Garamond",serif;
    font-size:26px;
    font-weight:600;
    color:var(--ink);
    margin-bottom:12px;
    letter-spacing:-0.01em;
  }
  .event.major h3{
    color:var(--accent-soft);
  }
  .event-body p{
    color:var(--ink-soft);
    font-size:16px;
    max-width:580px;
  }
  .event-body p .tag{
    display:inline-block;
    font-size:11px;
    letter-spacing:0.15em;
    text-transform:uppercase;
    color:var(--gold);
    margin-right:8px;
    padding:2px 8px;
    border:1px solid var(--gold);
    border-radius:2px;
    vertical-align:middle;
  }

  /* Bilan */
  section.toll{
    padding:80px 0;
    border-top:1px solid var(--rule);
    border-bottom:1px solid var(--rule);
    background:linear-gradient(to bottom, transparent, rgba(168,51,42,0.04), transparent);
  }

  .toll-grid{
    display:grid;
    grid-template-columns:1.1fr 1fr;
    gap:64px;
    align-items:start;
  }
  .toll-text h2{
    font-family:"Cormorant Garamond",serif;
    font-size:clamp(36px,5vw,56px);
    font-weight:500;
    line-height:1.05;
    margin-bottom:24px;
    letter-spacing:-0.01em;
  }
  .toll-text h2 em{
    font-style:italic;
    color:var(--accent-soft);
  }
  .toll-text p{
    color:var(--ink-soft);
    margin-bottom:1em;
    font-size:16px;
  }
  .toll-text .source-note{
    font-size:13px;
    color:var(--ink-mute);
    border-left:2px solid var(--accent);
    padding-left:16px;
    margin-top:24px;
    font-style:italic;
    line-height:1.6;
  }

  .toll-estimates{
    display:flex;
    flex-direction:column;
    gap:1px;
    background:var(--rule);
    border:1px solid var(--rule);
  }
  .estimate{
    background:var(--bg-2);
    padding:22px 24px;
    display:grid;
    grid-template-columns:1fr auto;
    gap:16px;
    align-items:center;
    transition:background 0.3s;
  }
  .estimate:hover{background:#1c1a15}
  .estimate .label{
    font-size:13px;
    color:var(--ink-soft);
    line-height:1.5;
  }
  .estimate .label strong{
    display:block;
    color:var(--ink);
    font-size:14px;
    margin-bottom:3px;
    font-weight:500;
  }
  .estimate .value{
    font-family:"Cormorant Garamond",serif;
    font-size:28px;
    font-weight:600;
    color:var(--accent-soft);
    text-align:right;
    letter-spacing:-0.01em;
    white-space:nowrap;
  }

  /* Citations / footer */
  .quote-block{
    padding:80px 0 40px;
    text-align:center;
    max-width:780px;
    margin:0 auto;
  }
  .quote-block blockquote{
    font-family:"Cormorant Garamond",serif;
    font-style:italic;
    font-size:clamp(22px,3vw,32px);
    line-height:1.4;
    color:var(--ink);
    margin-bottom:24px;
    position:relative;
  }
  .quote-block blockquote::before,
  .quote-block blockquote::after{
    content:"";
    display:block;
    width:40px;
    height:1px;
    background:var(--accent);
    margin:24px auto;
  }
  .quote-block cite{
    font-style:normal;
    font-size:13px;
    letter-spacing:0.2em;
    text-transform:uppercase;
    color:var(--ink-mute);
  }

  footer.colophon{
    padding:48px 0 64px;
    border-top:1px solid var(--rule);
    margin-top:40px;
    font-size:13px;
    color:var(--ink-mute);
    display:flex;
    flex-wrap:wrap;
    justify-content:space-between;
    gap:24px;
    line-height:1.7;
  }
  footer.colophon a{
    color:var(--ink-soft);
    text-decoration:none;
    border-bottom:1px solid var(--rule);
    transition:border-color 0.3s, color 0.3s;
  }
  footer.colophon a:hover{
    color:var(--accent-soft);
    border-color:var(--accent-soft);
  }

  /* Responsive */
  @media (max-width:760px){
    .container{padding:0 22px}
    header.masthead{padding:48px 0 32px}
    .timeline-rail::before{left:84px}
    .event{grid-template-columns:84px 1fr;gap:20px}
    .event::before{left:79px}
    .date{padding-top:28px}
    .date .day{font-size:28px}
    .event-body{padding:24px 0 0 28px}
    .toll-grid{grid-template-columns:1fr;gap:40px}
    .meta-bar{gap:24px}
  }

  @media (prefers-reduced-motion: reduce){
    .event{opacity:1;transform:none;transition:none}
  }
</style>
</head>
<body>

<div class="container">

  <header class="masthead">
    <div class="dateline">Pékin · République populaire de Chine · 1989</div>
    <h1 class="title">Place Tian'anmen,<br><em>avril–juin 1989</em></h1>
    <p class="lede">Chronologie d'un mouvement populaire étouffé dans le sang, et d'une nuit dont le bilan reste, plus de trois décennies plus tard, l'objet d'une guerre des chiffres.</p>

    <div class="meta-bar">
      <div><strong>Durée</strong>50 jours, du 15 avril au 9 juin 1989</div>
      <div><strong>Lieu</strong>Place Tian'anmen &amp; Pékin intra-muros</div>
      <div><strong>Acteurs</strong>Étudiants, ouvriers, armée populaire</div>
      <div><strong>Issue</strong>Répression militaire</div>
    </div>
  </header>

  <section class="intro">
    <p>Né dans le sillage de la mort de Hu Yaobang, réformateur évincé du Parti, le mouvement de la place Tian'anmen réunit en quelques semaines étudiants, ouvriers et citoyens de Pékin autour d'exigences de réforme politique, de liberté de la presse et de lutte contre la corruption. Il se termine dans la nuit du 3 au 4 juin par l'intervention de l'Armée populaire de libération contre la population civile. Les chiffres des victimes n'ont jamais fait l'objet d'un recensement public indépendant.</p>
  </section>

  <section class="timeline">
    <div class="section-label">Chronologie</div>
    <div class="timeline-rail">

      <article class="event major">
        <div class="date"><span class="day">15</span><span class="month">Avril</span></div>
        <div class="event-body">
          <h3>Mort de Hu Yaobang</h3>
          <p><span class="tag">Origine</span>Ancien secrétaire général du Parti, évincé en 1987 pour sa bienveillance envers les mouvements étudiants, Hu Yaobang meurt d'une crise cardiaque. Sa mémoire devient le catalyseur d'un mécontentement diffus : dépôts de gerbes, affiches manuscrites (dazibao) et rassemblements spontanés apparaissent sur le campus de l'Université de Pékin.</p>
        </div>
      </article>

      <article class="event">
        <div class="date"><span class="day">22</span><span class="month">Avril</span></div>
        <div class="event-body">
          <h3>Funérailles officielles</h3>
          <p>La cérémonie se tient au Grand Palais du Peuple, bordant la place Tian'anmen. Des dizaines de milliers d'étudiants s'y massent et refusent de quitter les lieux. C'est la première occupation durable de la place, à quelques jours du 4 mai, anniversaire symbolique du Mouvement du 4 Mai 1919.</p>
        </div>
      </article>

      <article class="event major">
        <div class="date"><span class="day">26</span><span class="month">Avril</span></div>
        <div class="event-body">
          <h3>Éditorial du Quotidien du Peuple</h3>
          <p><span class="tag">Durcissement</span>Sous l'impulsion de Deng Xiaoping, le Quotidien du Peuple qualifie le mouvement de « troubles » et de « conjuration » visant à renverser le Parti. Ce durcissement abrupt radicalise les étudiants, qui répondent par une manifestation de masse le 27 avril.</p>
        </div>
      </article>

      <article class="event">
        <div class="date"><span class="day">4</span><span class="month">Mai</span></div>
        <div class="event-body">
          <h3>Manifestation du 4 Mai</h3>
          <p>En écho au mouvement historique de 1919, plus de 100 000 étudiants défilent dans Pékin. Le mouvement s'étend à d'autres villes : Shanghai, Chengdu, Guangzhou, Xi'an. Des revendications communes émergent : dialogue avec le gouvernement, liberté de la presse, bilan public des fortunes des dirigeants.</p>
        </div>
      </article>

      <article class="event major">
        <div class="date"><span class="day">13</span><span class="month">Mai</span></div>
        <div class="event-body">
          <h3>Début de la grève de la faim</h3>
          <p><span class="tag">Climat</span>Quelques jours avant la visite à Pékin du dirigeant soviétique Mikhaïl Gorbatchev — première rencontre sino-soviétique au sommet depuis trente ans —, environ 3 000 étudiants entament une grève de la faim sur la place. La couverture internationale s'intensifie. Plus d'un million de personnes rejoignent la place en soutien.</p>
        </div>
      </article>

      <article class="event">
        <div class="date"><span class="day">19</span><span class="month">Mai</span></div>
        <div class="event-body">
          <h3>Visite de Zhao Ziyang</h3>
          <p>Le secrétaire général du Parti, Zhao Ziyang, favorable au dialogue, se rend sur la place au milieu de la nuit et prononce un discours adieu aux grévistes : « Nous sommes venus trop tard. » Ce sera sa dernière apparition publique. Il sera placé en résidence surveillée jusqu'à sa mort en 2005.</p>
        </div>
      </article>

      <article class="event major">
        <div class="date"><span class="day">20</span><span class="month">Mai</span></div>
        <div class="event-body">
          <h3>Loi martiale</h3>
          <p><span class="tag">Escalade</span>Le gouvernement décrète la loi martiale à Pékin. Des colonnes blindées tentent de pénétrer dans la ville mais sont bloquées par des centaines de milliers d'habitants formant des barrages humains. Les chars se retirent temporairement — dernière hésitation du régime avant la répression finale.</p>
        </div>
      </article>

      <article class="event major">
        <div class="date"><span class="day">3</span><span class="month">Juin</span></div>
        <div class="event-body">
          <h3>La nuit du 3 au 4 juin</h3>
          <p><span class="tag">Massacre</span>En fin de soirée, l'armée reçoit l'ordre de dégager la place à tout prix. Des chars et des blindés pénètrent par les avenues ouest (Chang'an) et sud de Pékin, tirant à balles réelles sur les barrages civils. Les combats de rue font des morts bien avant d'atteindre la place elle-même. La place est vidée dans la matinée du 4 juin.</p>
        </div>
      </article>

      <article class="event">
        <div class="date"><span class="day">5</span><span class="month">Juin</span></div>
        <div class="event-body">
          <h3>L'Homme au char</h3>
          <p>Sur l'avenue Chang'an, un homme seul, sac à la main, s'interpose devant une colonne de chars. Photographié par Jeff Widener (Associated Press), Stuart Franklin (Magnum) et plusieurs autres, l'image fait le tour du monde. L'identité et le sort de cet homme restent inconnus.</p>
        </div>
      </article>

      <article class="event">
        <div class="date"><span class="day">9</span><span class="month">Juin</span></div>
        <div class="event-body">
          <h3>Deng Xiaoping paraît</h3>
          <p>Deng Xiaoping apparaît publiquement pour la première fois depuis le déclenchement de la crise, félicitant les unités de l'armée. Le message est clair : la ligne dure a triomphé, et la répression est assumée. Les purges commencent dans les universités, les rédactions et les administrations.</p>
        </div>
      </article>

    </div>
  </section>

  <section class="toll">
    <div class="toll-grid">
      <div class="toll-text">
        <h2>Un bilan <em>en suspens</em></h2>
        <p>Aucun recensement public et indépendant des victimes n'a jamais été mené. Le gouvernement chinois a longtemps minimisé le nombre des morts, avant d'arrêter presque toute communication officielle sur le sujet. À l'inverse, plusieurs sources diplomatiques et journalistiques étrangères ont produit des estimations très différentes.</p>
        <p>La disparité tient à la durée retenue (la nuit seule, ou la semaine du 3 au 9 juin), au périmètre (la place seule, ou l'ensemble des quartiers de Pékin où l'armée a tiré), et à la difficulté de distinguer morts civils et militaires — une vingtaine de soldats ont également été tués, parfois lynchés par la foule.</p>
        <p class="source-note">Le dossier britannique du Foreign Office, déclassifié fin 2017, demeure la seule estimation produite par une chancellerie occidentale à partir de sources then-présentes à Pékin. Aucune de ces estimations ne saurait être tenue pour définitive.</p>
      </div>

      <div class="toll-estimates" aria-label="Estimations du nombre de victimes">
        <div class="estimate">
          <div class="label"><strong>Gouvernement chinois (chiffres officiels)</strong>Annoncés le 6 juin 1989, jamais révisés publiquement.</div>
          <div class="value">~ 200–300</div>
        </div>
        <div class="estimate">
          <div class="label"><strong>Croix-Rouge chinoise</strong>Estimation initialement communiquée puis

