    font-family:"Helvetica Neue",Arial,sans-serif;
    font-size:12px;
    letter-spacing:0.22em;
    text-transform:uppercase;
    color:var(--accent);
    font-weight:700;
    margin-bottom:6px;
  }
  .date .daynum{
