    letter-spacing:-0.01em;
  }
  .entry p{font-size:17px;color:#3a342e;max-width:720px}
  .entry p+p{margin-top:10px}

  .pull{
    margin:14px 0 6px;
    padding:14px 18px;
    background:var(--paper-2);
    border-left:3px solid var(--accent-2);
    font-style:italic;
    font-size:17px;
    color:var(--ink);
    max-width:680px;
  }

  .casualties{
    margin-top:90px;
    padding-top:34px;
    border-top:3px double var(--rule);
  }
  .casualties h3{
    font-family:"Helvetica Neue",Arial,sans-serif;
    font-size:12px;letter-spacing:0.28em;text-transform:uppercase;
    color:var(--accent);font-weight:700;margin-bottom:8px;
  }
  .casualties h4{
    font-size:clamp(28px,3.4vw,44px);
    font-weight:800;letter-spacing:-0.01em;line-height:1.05;
    margin-bottom:26px;
  }

  .toll-grid{
    display:grid;
    grid-template-columns:repeat(auto-fit,minmax(220px,1fr));
    gap:18px;
  }
  .toll{
    background:var(--paper-2);
    padding:22px 22px 20px;
    border-top:4px solid var(--accent);
    position:relative;
  }
  .toll .num{
    font-size:38px;font-weight:900;letter-spacing:-0.02em;
    line-height:1;color:var(--ink);
  }
  .toll .range{color:var(--accent);font-weight:800}
  .toll .src{
    font-family:"Helvetica Neue",Arial,sans-serif;
    font-size:11px;letter-spacing:0.16em;text-transform:uppercase;
    color:var(--muted);margin-top:14px;line-height:1.7;
  }
  .toll .src strong{color:var(--ink);display:block;font-size:12px;letter-spacing:0.2em}

  .note{
    margin-top:32px;
    font-size:14px;color:var(--muted);
    max-width:760px;line-height:1.7;
    border-top:1px solid #d8cdbb;
    padding-top:18px;
  }
  .note strong{color:var(--ink)}

  footer{
    border-top:1px solid var(--rule);
    padding:28px 6vw 60px;
