Here's a complete single-file HTML page. It's a fact-based chronology with the key documented dates from April through June 1989, and a death-toll panel that reflects the fact that no official figure was ever released and estimates vary widely.

```html
<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Tiananmen Square, 1989 — A Chronology</title>
<meta name="description" content="A timeline of the Tiananmen Square protests and their suppression, April–June 1989, with key dates and notes on the estimated death toll.">
<link rel="preconnect" href="https://fonts.googleapis.com">
<link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
<link href="https://fonts.googleapis.com/css2?family=Cormorant+Garamond:ital,wght@0,500;0,600;0,700;1,500&family=Inter:wght@400;500;600;700&display=swap" rel="stylesheet">
<style>
  :root{
    --paper:#f6f3ee;
    --card:#fffdfb;
    --ink:#1c1a16;
    --muted:#6f685f;
    --line:#dcd5c9;
    --accent:#9e2233;
    --accent-soft:#f2e3e4;
    --maxw:1080px;
    --serif:"Cormorant Garamond", Georgia, "Times New Roman", serif;
    --sans:"Inter", system-ui, -apple-system, "Segoe UI", sans-serif;
    --mono: ui-monospace, "SFMono-Regular", "Cascadia Code", Menlo, monospace;
  }
  *{ box-sizing:border-box; }
  html{ scroll-behavior:smooth; }
  body{
    margin:0;
    background:var(--paper);
    color:var(--ink);
    font-family:var(--sans);
    line-height:1.65;
    -webkit-font-smoothing:antialiased;
    background-image:
      radial-gradient(1200px 500px at 80% -10%, #efe9df 0%, rgba(0,0,0,0) 60%),
      radial-gradient(900px 500px at -10% 20%, #f1ece3 0%, rgba(0,0,0,0) 55%);
    background-attachment:fixed;
  }
  .wrap{ max-width:var(--maxw); margin:0 auto; padding:0 24px; }

  /* ---------- Masthead ---------- */
  .masthead{ padding:64px 0 28px; }
  .toprule{
    display:flex; justify-content:space-between; align-items:center;
    gap:16px; flex-wrap:wrap;
    border-top:2px solid var(--ink);
    padding-top:14px; margin-bottom:40px;
    font-family:var(--mono); font-size:12px; letter-spacing:.14em;
    text-transform:uppercase; color:var(--muted);
  }
  .toprule b{ color:var(--ink); font-weight:600; }
  .toprule .dot{ width:9px; height:9px; border-radius:50%; background:var(--accent); display:inline-block; margin-right:8px; vertical-align:middle; }
  h1{
    font-family:var(--serif);
    font-weight:600;
    font-size:clamp(2.6rem, 7vw, 5rem);
    line-height:1.02;
    letter-spacing:-.01em;
    margin:0 0 18px;
  }
  h1 em{ font-style:italic; color:var(--accent); }
  .dek{
    max-width:62ch;
    font-size:clamp(1rem, 1.4vw, 1.18rem);
    color:#3a352f;
    margin:0 0 8px;
  }

  /* ---------- Death toll panel ---------- */
  .toll{
    margin:44px 0 8px;
    border:1px solid var(--line);
    border-left:5px solid var(--accent);
    background:var(--card);
    border-radius:4px;
    padding:26px 28px;
    box-shadow:0 1px 0 rgba(0,0,0,.02);
  }
  .toll .label{
    font-family:var(--mono); font-size:12px; letter-spacing:.16em;
    text-transform:uppercase; color:var(--accent); margin:0 0 10px;
  }
  .toll .range{
    font-family:var(--serif); font-weight:700;
    font-size:clamp(2rem, 4.5vw, 3rem); line-height:1;
    margin:0 0 14px;
  }
  .toll .range span{ color:var(--accent); }
  .toll p{ margin:0; color:#403a33; max-width:74ch; font-size:.98rem; }
  .toll .fn{ margin-top:12px; font-size:.8rem; color:var(--muted); }

  /* ---------- Timeline ---------- */
  .timeline{ position:relative; margin:48px 0 0; padding:0 0 8px; }
  .timeline::before{
    content:""; position:absolute; left:20px; top:6px; bottom:6px;
    width:2px; background:linear-gradient(var(--line) 0%, var(--line) 85%, rgba(0,0,0,0));
  }
  .month{
    position:relative; margin:34px 0 18px;
    display:flex; align-items:baseline; gap:14px;
  }
  .month h2{
    font-family:var(--serif); font-weight:700;
    font-size:1.7rem; margin:0; letter-spacing:.02em;
  }
  .month .tag{
    font-family:var(--mono); font-size:11px; letter-spacing:.12em;
    text-transform:uppercase; color:var(--muted);
    border:1px solid var(--line); border-radius:20px; padding:3px 10px;
  }
  .month::before{
    content:""; position:absolute; left:12px; top:.55em;
    width:18px; height:18px; border-radius:50%;
    background:var(--paper); border:2px solid var(--ink);
  }

  .entry{
    position:relative; margin:0 0 22px; padding-left:60px;
  }
  .entry::before{
    content:""; position:absolute; left:14px; top:4px;
    width:14px; height:14px; border-radius:50%;
    background:var(--card); border:2px solid var(--ink);
    transition:transform .25s ease, background .25s ease, border-color .25s ease;
  }
  .entry:hover::before{ transform:scale(1.35); background:var(--ink); }

  .card{
    background:var(--card);
    border:1px solid var(--line);
    border-radius:4px;
    padding:16px 18px;
    transition:transform .25s ease, box-shadow .25s ease, border-color .25s ease;
  }
  .entry:hover .card{
    transform:translateY(-3px);
    box-shadow:0 10px 26px -14px rgba(30,24,18,.35);
    border-color:#cfc6b8;
  }
  .date{
    font-family:var(--mono); font-size:.78rem; letter-spacing:.05em;
    color:var(--muted); margin-bottom:5px;
  }
  .entry h3{
    font-family:var(--serif); font-weight:700; font-size:1.35rem;
    line-height:1.15; margin:0 0 6px;
  }
  .entry p{ margin:0; font-size:.95rem; color:#3f3a33; }

  /* pivotal / June 3–4 emphasis */
  .entry.pivotal::before{ border-color:var(--accent); background:var(--accent); }
  .entry.pivotal .card{
    border-color:var(--accent-soft);
    background:linear-gradient(180deg, #fbf6f4, var(--card));
  }
  .entry.p

