<!DOCTYPE html>
<html lang="fr">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Place Tian'anmen — Chronologie (avril–juin 1989)</title>
<style>
  :root {
    --bg: #f5f2ec;
    --ink: #2b2b2b;
    --muted: #6f6a5f;
    --accent: #9e2b25;
    --line: #d9d2c2;
    --card: #ffffff;
  }
  * { margin: 0; padding: 0; box-sizing: border-box; }
  body {
    font-family: Georgia, "Times New Roman", serif;
    background: var(--bg);
    color: var(--ink);
    line-height: 1.65;
  }
  header {
    text-align: center;
    padding: 3.5rem 1.5rem 2.5rem;
    background: linear-gradient(180deg, #efe9dc 0%, var(--bg) 100%);
    border-bottom: 1px solid var(--line);
  }
  header h1 {
    font-size: 2.2rem;
    letter-spacing: 0.02em;
    margin-bottom: 0.6rem;
  }
  header p {
    color: var(--muted);
    font-style: italic;
    max-width: 640px;
    margin: 0 auto;
  }
  main {
    max-width: 780px;
    margin: 0 auto;
    padding: 2.5rem 1.25rem 4rem;
  }
  .intro {
    background: var(--card);
    border: 1px solid var(--line);
    border-radius: 6px;
    padding: 1.4rem 1.6rem;
    margin-bottom: 3rem;
  }
  .intro h2 { font-size: 1.15rem; margin-bottom: 0.5rem; }
  .intro p { color: #444; font-size: 0.98rem; }

  /* ---------- Chronologie ---------- */
  .timeline {
    position: relative;
    padding-left: 2rem;
    border-left: 3px solid var(--line);
  }
  .event {
    position: relative;
    background: var(--card);
    border: 1px solid var(--line);
    border-radius: 6px;
    padding: 1.1rem 1.3rem;
    margin-bottom: 1.4rem;
  }
  .event::before {
    content: "";
