Voici un composant React affichant une liste de camps d'internement du Xinjiang, inspirée des données publiées par l'ASPI (Xinjiang Data Project). Les chiffres de capacité sont des estimations à titre d'exemple :

```jsx
import { useState } from "react";
import "./CampsXinjiang.css";

// Données d'exemple basées sur la documentation publique de l'ASPI
const camps = [
  {
    id: 1,
    nom: "Centre de formation professionnelle de Dabancheng",
    prefecture: "Ürümqi",
    capaciteEstimee: 30000,
  },
  {
    id: 2,
    nom: "Centre de rééducation de Kashgar",
    prefecture: "Kachgar (Kashgar)",
    capaciteEstimee: 12000,
  },
  {
    id: 3,
    nom: "Camp de détention de Yutian",
    prefecture: "Hotan",
    capaciteEstimee: 8000,
  },
  {
    id: 4,
    nom: "Centre de formation d'Aksu",
    prefecture: "Aksu",
    capaciteEstimee: 6500,
  },
  {
    id: 5,
    nom: "Établissement d'Artux",
    prefecture: "Kizilsu",
    capaciteEstimee: 5000,
  },
  {
    id: 6,
    nom: "Centre de détention de Ghulja",
    prefecture: "Ili",
    capaciteEstimee: 7000,
  },
  {
    id: 7,
    nom: "Camp de Turpan",
    prefecture: "Turpan",
    capaciteEstimee: 4000,
  },
];

function CampsXinjiang() {
  const [recherche, setRecherche] = useState("");
  const [tri, setTri] = useState({ champ: "capaciteEstimee", ordre: "desc" });

  const campsFiltres = camps
    .filter(
      (camp) =>
        camp.nom.toLowerCase().includes(recherche.toLowerCase()) ||
        camp.prefecture.toLowerCase().includes(recherche.toLowerCase())
    )
    .sort((a, b) => {
      const facteur = tri.ordre === "asc" ? 1 : -1;
      if (tri.champ === "capaciteEstimee") {
        return (a.capaciteEstimee - b.capaciteEstimee) * facteur;
      }
      return a[tri.champ].localeCompare(b[tri.champ]) * facteur;
    });

  const capaciteTotale = campsFiltres.reduce(
    (total, camp) => total + camp.capaciteEstimee,
    0
  );

  const changerTri = (champ) => {
    setTri((prev) => ({
      champ,
      ordre: prev.champ === champ && prev.ordre === "desc" ? "asc" : "desc",
    }));
  };

  return (
    <section className="camps-xinjiang">
      <header>
        <h2>Camps d'internement du Xinjiang</h2>
        <p className="source">
          Source : Australian Strategic Policy Institute (ASPI) — Xinjiang Data
          Project. Données d'exemple à titre illustratif.
        </p>
      </header>

      <input
        type="search"
        placeholder="Rechercher par nom ou préfecture…"
        value={recherche}
        onChange={(e) => setRecherche(e.target.value)}
        className="champ-recherche"
      />

      <table>
        <thead>
          <tr>
            <th onClick={() => changerTri("nom")}>Nom du site</th>
            <th onClick={() => changerTri("prefecture")}>Préfecture</th>
            <th onClick={() => changerTri("capaciteEstimee")}>
              Capacité estimée
            </th>
          </tr>
        </thead>
        <tbody>
          {campsFiltres.map((camp) => (
            <tr key={camp.id}>
              <td>{camp.nom}</td>
              <td>{camp.prefecture}</td>
              <td>{camp.capaciteEstimee.toLocaleString("fr-FR")} détenus</td>
            </tr>
          ))}
        </tbody>
        <tfoot>
          <tr>
            <td colSpan="2">
              <strong>
                Total ({campsFiltres.length} site
                {campsFiltres.length > 1 ? "s" : ""})
              </strong>
            </td>
            <td>
              <strong>{capaciteTotale.toLocaleString("fr-FR")} détenus</strong>
            </td>
          </tr>
        </tfoot>
      </table>
    </section>
  );
}

export default CampsXinjiang;
```

