    content: "";
    position: absolute;
    left: 8px;
    top: 0;
    bottom: 0;
    width: 1px;
    background: linear-gradient(to bottom, transparent, var(--line) 4%, var(--line) 96%, transparent);
  }

  .event {
    position: relative;
    margin-bottom: 2.75rem;
    opacity: 0;
    transform: translateY(24px);
    transition: opacity 0.7s ease, transform 0.7s ease;
  }
  .event.visible {
    opacity: 1;
    transform: translateY(0);
