    content: "";
    position: absolute;
    left: -2.5rem;
    top: 0.55rem;
    width: 9px;
    height: 9px;
    margin-left: 4.5px;
    border-radius: 50%;
    background: var(--bg);
    border: 2px solid var(--accent);
    transform: translateX(-50%);
  }

