        }
        h2 {
            color: #555;
            margin-top: 30px;
        }
        .timeline {
            background-color: white;
            padding: 20px;
            border-radius: 5px;
            box-shadow: 0 0 10px rgba(0,0,0,0.1);
        }
        .event {
            margin-bottom: 20px;
            padding-left: 15px;
            border-left: 3px solid #8B0000;
        }
        .date {
            font-weight: bold;
            color: #8B0000;
        }
        .bilan {
            background-color: #f0f0f0;
            padding: 15px;
            border-radius: 5px;
